#!/usr/bin/env node
/**
 * Reference routing-data service for development.
 *
 * This server serves packages generated by build-region.sh. It can also clip
 * and build a package from a configured OSM extract when the app requests a
 * new region. On-demand builds are enabled by default; set
 * ROUTING_BUILD_ON_DEMAND=0 to disable them. It never synthesizes tiles or
 * manifests. It implements the same HTTP contract the app expects:
 *
 *   GET  /regions
 *   POST /packages
 *   POST /packages/estimate
 *   GET  /packages/:regionId
 *   GET  /packages/:regionId/manifest.json
 *   GET  /packages/:regionId/<package file>
 *
 * A separate production service may replace it, but must keep the contract and
 * checksums.
 */
import { createReadStream } from 'node:fs';
import { cp, mkdir, readdir, readFile, stat, writeFile } from 'node:fs/promises';
import http from 'node:http';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { buildRoutingPackage } from './builder.mjs';
import {
  DEFAULT_ENGINE_VERSION,
  boundsContain,
  expandBounds,
  parseBounds,
} from './lib.mjs';

const SCRIPT_DIR = path.dirname(fileURLToPath(import.meta.url));
const PORT = Number(process.env.PORT ?? 8787);
const HOST = process.env.HOST ?? '0.0.0.0';
const DATA_DIR = path.resolve(
  process.env.ROUTING_DATA_DIR ?? path.join(SCRIPT_DIR, 'data', 'regions'),
);
const RETRY_AFTER_SECONDS = Number(process.env.ROUTING_BUILD_RETRY_SECONDS ?? 20);
const REGION_ID_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;
const PACKAGE_FORMATS = new Set(['directory', 'zip']);
const ADOPT_PREBUILT = process.env.ROUTING_DATA_ADOPT_PREBUILT !== '0';
const BUILD_ON_DEMAND = process.env.ROUTING_BUILD_ON_DEMAND !== '0';
const buildJobs = new Map();
const buildQueue = [];
let buildActive = false;

const CONTENT_TYPES = new Map([
  ['.json', 'application/json; charset=utf-8'],
  ['.pbf', 'application/octet-stream'],
  ['.bin', 'application/octet-stream'],
  ['.tar', 'application/x-tar'],
  ['.gz', 'application/gzip'],
]);

async function readManifest(regionId) {
  if (!REGION_ID_PATTERN.test(regionId)) {
    return null;
  }

  try {
    const text = await readFile(
      path.join(DATA_DIR, regionId, 'manifest.json'),
      'utf8',
    );
    const manifest = JSON.parse(text);

    if (!manifest || manifest.regionId !== regionId) {
      return null;
    }

    return manifest;
  } catch (error) {
    if (error && error.code === 'ENOENT') {
      return null;
    }
    throw error;
  }
}

async function readJsonBody(request, limitBytes = 1024 * 1024) {
  const chunks = [];
  let total = 0;

  for await (const chunk of request) {
    total += chunk.length;

    if (total > limitBytes) {
      throw Object.assign(new Error('Request body too large.'), { statusCode: 413 });
    }

    chunks.push(chunk);
  }

  if (chunks.length === 0) {
    throw Object.assign(new Error('A JSON body is required.'), { statusCode: 400 });
  }

  try {
    return JSON.parse(Buffer.concat(chunks).toString('utf8'));
  } catch {
    throw Object.assign(new Error('Invalid JSON body.'), { statusCode: 400 });
  }
}

function validatePackageRequest(body) {
  if (!body || typeof body !== 'object') {
    throw Object.assign(new Error('Invalid package request.'), { statusCode: 400 });
  }

  const regionId = String(body.regionId ?? '');

  if (!REGION_ID_PATTERN.test(regionId)) {
    throw Object.assign(new Error('Invalid regionId.'), { statusCode: 400 });
  }

  const bounds = parseBounds(
    [body.bounds?.west, body.bounds?.south, body.bounds?.east, body.bounds?.north].join(','),
    'bounds',
  );
  const radiusKm = Number(body.radiusKm);
  const bufferKm = Number(body.bufferKm ?? 0);
  const packageFormat = String(body.packageFormat ?? 'directory');
  const engineVersion = String(body.valhallaEngineVersion ?? DEFAULT_ENGINE_VERSION);

  if (!Number.isFinite(radiusKm) || radiusKm <= 0 || radiusKm > 500) {
    throw Object.assign(new Error('Invalid radiusKm.'), { statusCode: 400 });
  }

  if (!Number.isFinite(bufferKm) || bufferKm < 0 || bufferKm > 100) {
    throw Object.assign(new Error('Invalid bufferKm.'), { statusCode: 400 });
  }

  if (!PACKAGE_FORMATS.has(packageFormat)) {
    throw Object.assign(
      new Error('packageFormat must be "directory" or "zip".'),
      { statusCode: 400 },
    );
  }

  if (!sameMajorMinor(engineVersion, DEFAULT_ENGINE_VERSION)) {
    throw Object.assign(
      new Error(
        `This server builds Valhalla ${DEFAULT_ENGINE_VERSION} tiles; it cannot satisfy ${engineVersion}.`,
      ),
      { statusCode: 409 },
    );
  }

  return {
    regionId,
    bounds,
    radiusKm,
    bufferKm,
    packageFormat,
    engineVersion,
    request: body,
  };
}

function sameMajorMinor(left, right) {
  const a = String(left).split('.');
  const b = String(right).split('.');
  return a[0] === b[0] && a[1] === b[1];
}

async function findCoveringPrebuilt(parsed) {
  if (!ADOPT_PREBUILT) {
    return null;
  }

  let entries;

  try {
    entries = await readdir(DATA_DIR, { withFileTypes: true });
  } catch (error) {
    if (error && error.code === 'ENOENT') {
      return null;
    }
    throw error;
  }

  for (const entry of entries) {
    if (!entry.isDirectory() || entry.name === parsed.regionId) {
      continue;
    }

    const manifest = await readManifest(entry.name);

    if (
      !manifest ||
      manifest.packageFormat !== 'directory' ||
      !sameMajorMinor(manifest.valhallaEngineVersion, parsed.engineVersion) ||
      manifest.radiusKm + 1e-9 < parsed.radiusKm ||
      !boundsContain(manifest.coverageBounds, parsed.bounds)
    ) {
      continue;
    }

    return { regionId: entry.name, manifest };
  }

  return null;
}

async function adoptPrebuiltPackage(parsed, source) {
  const targetDir = path.join(DATA_DIR, parsed.regionId);

  await mkdir(DATA_DIR, { recursive: true });
  await cp(path.join(DATA_DIR, source.regionId), targetDir, {
    recursive: true,
    force: false,
    errorOnExist: true,
  });

  const manifest = {
    ...source.manifest,
    regionId: parsed.regionId,
    regionName:
      String(parsed.request?.regionName ?? '').trim() ||
      source.manifest.regionName,
    bounds: parsed.bounds,
    radiusKm: parsed.radiusKm,
    bufferKm: parsed.bufferKm,
    createdAt: new Date().toISOString(),
    metadata: {
      ...(source.manifest.metadata ?? {}),
      adoptedFrom: source.regionId,
    },
  };

  await writeFile(
    path.join(targetDir, 'manifest.json'),
    `${JSON.stringify(manifest, null, 2)}\n`,
    'utf8',
  );

  return manifest;
}

function regionSummary(regionId, manifest) {
  return {
    regionId,
    regionName: manifest.regionName,
    bounds: manifest.bounds,
    coverageBounds: manifest.coverageBounds,
    radiusKm: manifest.radiusKm,
    packageFormat: manifest.packageFormat,
    valhallaDataVersion: manifest.valhallaDataVersion,
    valhallaEngineVersion: manifest.valhallaEngineVersion,
    valhallaEngineCompatibility: manifest.valhallaEngineCompatibility ?? null,
    downloadSizeBytes: manifest.downloadSizeBytes,
    createdAt: manifest.createdAt,
    manifestUrl: `/packages/${encodeURIComponent(regionId)}/manifest.json`,
  };
}

async function listRegions() {
  let entries;

  try {
    entries = await readdir(DATA_DIR, { withFileTypes: true });
  } catch (error) {
    if (error && error.code === 'ENOENT') {
      return [];
    }
    throw error;
  }

  const regions = [];

  for (const entry of entries) {
    if (!entry.isDirectory()) {
      continue;
    }

    const manifest = await readManifest(entry.name);

    if (manifest) {
      regions.push(regionSummary(entry.name, manifest));
    }
  }

  return regions.sort((left, right) =>
    left.regionName.localeCompare(right.regionName),
  );
}

function sendJson(response, statusCode, payload, extraHeaders = {}) {
  const body = Buffer.from(`${JSON.stringify(payload, null, 2)}\n`, 'utf8');
  response.writeHead(statusCode, {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Length': body.byteLength,
    'Cache-Control': 'no-store',
    ...extraHeaders,
  });
  response.end(body);
}

function buildingPayload(regionId) {
  return {
    status: 'building',
    regionId,
    estimatedSizeBytes: null,
    retryAfterSeconds: RETRY_AFTER_SECONDS,
  };
}

async function servePackageFile(response, regionId, relativeSegments) {
  const packageRoot = path.join(DATA_DIR, regionId);
  const target = path.resolve(packageRoot, ...relativeSegments);
  const rootPrefix = `${path.resolve(packageRoot)}${path.sep}`;

  if (!target.startsWith(rootPrefix)) {
    sendJson(response, 400, { error: 'Unsafe package path.' });
    return;
  }

  let info;

  try {
    info = await stat(target);
  } catch (error) {
    if (error && error.code === 'ENOENT') {
      sendJson(response, 404, { error: 'Package file not found.' });
      return;
    }
    throw error;
  }

  if (!info.isFile()) {
    sendJson(response, 404, { error: 'Package file not found.' });
    return;
  }

  const contentType =
    CONTENT_TYPES.get(path.extname(target).toLowerCase()) ?? 'application/octet-stream';

  response.writeHead(200, {
    'Content-Type': contentType,
    'Content-Length': info.size,
    'Cache-Control': 'public, max-age=31536000, immutable',
  });

  if (response.req.method === 'HEAD') {
    response.end();
    return;
  }

  createReadStream(target).pipe(response);
}

function enqueueBuild(parsed) {
  const current = buildJobs.get(parsed.regionId);

  if (current?.state === 'building') {
    return;
  }

  buildJobs.set(parsed.regionId, {
    state: 'building',
    error: null,
    startedAt: new Date().toISOString(),
  });
  buildQueue.push(parsed);
  void drainBuildQueue();
}

async function drainBuildQueue() {
  if (buildActive) {
    return;
  }

  buildActive = true;

  try {
    while (buildQueue.length > 0) {
      const parsed = buildQueue.shift();
      console.log(`Building routing package ${parsed.regionId}...`);

      try {
        const manifest = await buildRoutingPackage(parsed, {
          dataDir: DATA_DIR,
          engineVersion: DEFAULT_ENGINE_VERSION,
        });

        buildJobs.set(parsed.regionId, {
          state: 'ready',
          error: null,
          finishedAt: new Date().toISOString(),
        });
        console.log(
          `Built ${parsed.regionId} (${manifest.downloadSizeBytes} bytes).`,
        );
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);

        buildJobs.set(parsed.regionId, {
          state: 'failed',
          error: message,
          finishedAt: new Date().toISOString(),
        });
        console.error(`Failed to build ${parsed.regionId}: ${message}`);
      }
    }
  } finally {
    buildActive = false;
  }
}

async function handleRequest(request, response) {
  const url = new URL(request.url ?? '/', `http://${request.headers.host ?? 'localhost'}`);
  const pathname = url.pathname;

  if (request.method === 'OPTIONS') {
    response.writeHead(204);
    response.end();
    return;
  }

  if (request.method === 'GET' && pathname === '/health') {
    sendJson(response, 200, {
      ok: true,
      dataDir: DATA_DIR,
      engineVersion: DEFAULT_ENGINE_VERSION,
      packageFormats: [...PACKAGE_FORMATS],
      buildOnDemand: BUILD_ON_DEMAND,
      adoptPrebuilt: ADOPT_PREBUILT,
    });
    return;
  }

  if (
    request.method === 'GET' &&
    (pathname === '/regions' || pathname === '/regions/')
  ) {
    sendJson(response, 200, { regions: await listRegions() });
    return;
  }

  if (request.method === 'POST' && pathname === '/packages/estimate') {
    const parsed = validatePackageRequest(await readJsonBody(request));

    if (parsed.packageFormat === 'zip') {
      sendJson(response, 501, {
        error:
          'This reference server only produces directory packages. Set EXPO_PUBLIC_ROUTING_PACKAGE_FORMAT=directory.',
      });
      return;
    }

    const manifest = await readManifest(parsed.regionId);
    const prebuilt = manifest ? null : await findCoveringPrebuilt(parsed);
    const ready = manifest !== null || prebuilt !== null;
    const job = buildJobs.get(parsed.regionId);

    sendJson(response, 200, {
      estimatedSizeBytes:
        manifest?.downloadSizeBytes ??
        prebuilt?.manifest.downloadSizeBytes ??
        null,
      coverageBounds:
        manifest?.coverageBounds ??
        prebuilt?.manifest.coverageBounds ??
        expandBounds(parsed.bounds, parsed.bufferKm),
      valhallaDataVersion:
        manifest?.valhallaDataVersion ??
        prebuilt?.manifest.valhallaDataVersion ??
        null,
      valhallaEngineVersion:
        manifest?.valhallaEngineVersion ??
        prebuilt?.manifest.valhallaEngineVersion ??
        DEFAULT_ENGINE_VERSION,
      ready,
      building: job?.state === 'building',
      buildOnDemand: BUILD_ON_DEMAND && !ready,
    });
    return;
  }

  if (request.method === 'POST' && pathname === '/packages') {
    const parsed = validatePackageRequest(await readJsonBody(request));

    if (parsed.packageFormat === 'zip') {
      sendJson(response, 501, {
        error:
          'This reference server only produces directory packages. Set EXPO_PUBLIC_ROUTING_PACKAGE_FORMAT=directory.',
      });
      return;
    }

    const manifest = await readManifest(parsed.regionId);

    if (manifest) {
      sendJson(response, 200, manifest);
      return;
    }

    const prebuilt = await findCoveringPrebuilt(parsed);

    if (prebuilt) {
      const adopted = await adoptPrebuiltPackage(parsed, prebuilt);
      console.log(
        `Adopted prebuilt package ${prebuilt.regionId} as ${parsed.regionId}.`,
      );
      sendJson(response, 200, adopted);
      return;
    }

    if (BUILD_ON_DEMAND) {
      enqueueBuild(parsed);
      console.log(`Queued on-demand build for ${parsed.regionId}.`);
    } else {
      sendJson(response, 503, {
        error:
          'No routing package covers this region. Provide a prebuilt package or enable on-demand builds (the default; set ROUTING_BUILD_ON_DEMAND=0 to disable).',
      });
      return;
    }

    sendJson(response, 202, buildingPayload(parsed.regionId), {
      'Retry-After': String(RETRY_AFTER_SECONDS),
    });
    return;
  }

  const match = pathname.match(/^\/packages\/([^/]+)(?:\/(.*))?$/);

  if (!match) {
    sendJson(response, 404, { error: 'Not found.' });
    return;
  }

  let regionId;

  try {
    regionId = decodeURIComponent(match[1]);
  } catch {
    sendJson(response, 400, { error: 'Invalid regionId encoding.' });
    return;
  }

  if (!REGION_ID_PATTERN.test(regionId)) {
    sendJson(response, 400, { error: 'Invalid regionId.' });
    return;
  }

  const rest = match[2] ?? '';

  if (request.method !== 'GET' && request.method !== 'HEAD') {
    sendJson(response, 405, { error: 'Method not allowed.' });
    return;
  }

  if (rest === '' || rest === 'manifest.json') {
    const manifest = await readManifest(regionId);

    if (manifest) {
      sendJson(response, 200, manifest);
      return;
    }

    if (rest === 'manifest.json') {
      sendJson(response, 404, { error: 'Manifest not found.' });
      return;
    }

    const job = buildJobs.get(regionId);

    if (job?.state === 'failed') {
      sendJson(response, 502, {
        error: 'Routing package build failed.',
        detail: job.error,
      });
      return;
    }

    sendJson(response, 202, buildingPayload(regionId), {
      'Retry-After': String(RETRY_AFTER_SECONDS),
    });
    return;
  }

  const segments = rest.split('/').map((segment) => {
    try {
      return decodeURIComponent(segment);
    } catch {
      return segment;
    }
  });

  if (
    segments.some(
      (segment) =>
        segment.length === 0 ||
        segment === '.' ||
        segment === '..' ||
        segment.includes('\0') ||
        segment.includes('\\'),
    )
  ) {
    sendJson(response, 400, { error: 'Unsafe package path.' });
    return;
  }

  await servePackageFile(response, regionId, segments);
}

const server = http.createServer((request, response) => {
  response.setHeader('Access-Control-Allow-Origin', '*');
  response.setHeader('Access-Control-Allow-Methods', 'GET,HEAD,POST,OPTIONS');
  response.setHeader('Access-Control-Allow-Headers', 'Content-Type');

  handleRequest(request, response).catch((error) => {
    const statusCode = error?.statusCode ?? 500;
    console.error(error);
    if (!response.headersSent) {
      sendJson(response, statusCode, {
        error: statusCode === 500 ? 'Internal server error.' : error.message,
      });
    } else {
      response.destroy();
    }
  });
});

await mkdir(DATA_DIR, { recursive: true });

server.listen(PORT, HOST, () => {
  console.log(`Routing-data service listening on http://${HOST}:${PORT}`);
  if (HOST === '0.0.0.0') {
    console.log(
      'The service is reachable from physical devices on the same LAN via this computer’s LAN IP.',
    );
  }
  console.log(`Serving packages from ${DATA_DIR}`);

  if (BUILD_ON_DEMAND) {
    console.log(
      'On-demand builds are enabled: missing regions are clipped and built from ROUTING_OSM_SOURCES / ROUTING_OSM_EXTRACT.',
    );
  } else {
    console.log(
      'On-demand builds are disabled; run build-region.sh or unset ROUTING_BUILD_ON_DEMAND=0.',
    );
  }

  if (ADOPT_PREBUILT) {
    console.log(
      'Prebuilt adoption is enabled: matching packages are copied to requested region IDs.',
    );
  }
});
